local rdmdata = {}
rdmdata.firstname = function() return first[math.random(#first)] end
rdmdata.lastname = function() return last[math.random(#last)] end
rdmdata.fullname = function() return table.concat({rdmdata.firstname(), " ", rdmdata.lastname()}) end
rdmdata.mood = function() return random_moods[math.random(#random_moods)] end
rdmdata.countrycode = function() return countryindex[math.random(#countryindex)] end
rdmdata.country = function() return countryindex[rdmdata.countrycode()] end
rdmdata.age = function(min, max) return math.random(math.max(1, min or 1), math.max(2, max or 2)) end
rdmdata.gender = function() return genders[math.random(#genders)] end
rdmdata.GetCountry = function(indx) return countries[indx] end
rdmdata.GetGenderModel = function(gender)
	local mdls = gendermodels[gender]
	mdls = istable(mdls) and mdls or gendermodels["male"]

	return mdls[math.random(#mdls)]
end

function ENT:GetRandomData(dtype, ...)
	dtype = dtype:lower()
	if not rdmdata[dtype] then return end
	return rdmdata[dtype](...)
end

function ENT:GetCountry(code)
	return rdmdata.GetCountry(code)
end

function ENT:GetGenderModel(gen)
	gen = isstring(gen) and gen or ""
	return rdmdata.GetGenderModel(gen:lower())
end